import React from 'react';
import './Logo.css';

const Logo = ({ size = 'medium', showTagline = false }) => {
  return (
    <div className={`logo-container ${size}`}>
      <div className="logo-wrapper">
        <svg className="logo-icon" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
          <path d="M12 2L2 7L12 12L22 7L12 2Z" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
          <path d="M2 17L12 22L22 17" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
          <path d="M2 12L12 17L22 12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
          <circle cx="12" cy="12" r="2" fill="#4CAF50"/>
          <path d="M12 8V16" stroke="#4CAF50" strokeWidth="2" strokeLinecap="round"/>
          <path d="M8 12H16" stroke="#4CAF50" strokeWidth="2" strokeLinecap="round"/>
        </svg>
        <h1 className="brand-title">
          Solar<span className="brand-highlight">AI</span>
        </h1>
      </div>
      {showTagline && (
        <p className="brand-tagline">Intelligent Solar Panel Management</p>
      )}
    </div>
  );
};

export default Logo;
